// ─── Batch 7 | Verify HMAC Signature ─────────────────────────────────────────
// Verifies HMAC-SHA256 signature on the raw webhook body.
// Signature expected in header x-offer-signature: sha256=<hex>
// Computed over raw body bytes using secret from env var OFFER_WEBHOOK_SECRET.
// Uses timing-safe comparison to prevent timing oracle attacks.
// Validates requestedAt replay window: rejects expired (>5 min) AND future (>30s).
//
// RETURNS (never throws):
//   success: { ...payload, _hmacValid: true }
//   failure: { _hmacValid: false, _hmacError: '...' }
// Routes through IF: Valid Signature → Respond 202 or → Respond 403.
// ─────────────────────────────────────────────────────────────────────────────

const crypto    = require('crypto');
const inputItem = $input.first();
const item      = inputItem.json;

// ── Raw body: Webhook rawBody:true stores bytes in binary['data'] as base64 ──
const b64     = inputItem.binary?.['data']?.data ?? '';
const rawBody = b64
  ? Buffer.from(b64, 'base64').toString('utf8')
  : JSON.stringify(item.body ?? {});

const headers   = item.headers ?? {};
const sigHeader = String(headers['x-offer-signature'] ?? '').trim();
const secret    = $env['OFFER_WEBHOOK_SECRET'];

if (!sigHeader) {
  return [{ json: { _hmacValid: false, _hmacError: 'Missing x-offer-signature header.' } }];
}
if (!secret) {
  return [{ json: { _hmacValid: false, _hmacError: 'OFFER_WEBHOOK_SECRET not configured.' } }];
}

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(rawBody, 'utf8').digest('hex');

// ── Timing-safe comparison ──
// Both buffers are SHA-256 hex digests with 'sha256=' prefix: always (7+64)=71 bytes
// for a correctly-formatted signature. Length mismatch means a non-hex or truncated
// signature — safe to reject before the constant-time path (length reveals no secret).
const sigBuf = Buffer.from(sigHeader, 'utf8');
const expBuf = Buffer.from(expected,  'utf8');
let valid = false;
if (sigBuf.length === expBuf.length) {
  valid = crypto.timingSafeEqual(sigBuf, expBuf);
} else {
  valid = false; // Explicit: non-hex/truncated signature is always invalid
}

if (!valid) {
  return [{ json: { _hmacValid: false, _hmacError: 'HMAC signature mismatch.' } }];
}

// ── Parse body after verification ──
let payload;
try {
  payload = JSON.parse(rawBody);
} catch (e) {
  return [{ json: { _hmacValid: false, _hmacError: 'Invalid JSON body: ' + e.message } }];
}

// ── Replay protection ──
// requestedAt is REQUIRED. Reject if:
//   - absent (replay protection requires it)
//   - in the future beyond 30s clock skew tolerance (prevents far-future permanent replay bypass)
//   - older than 5 minutes (expired)
if (!payload.requestedAt) {
  return [{ json: { _hmacValid: false, _hmacError: 'Missing requestedAt. Replay protection requires an ISO timestamp.' } }];
}
const age = Date.now() - new Date(payload.requestedAt).getTime();
if (age < -30 * 1000) {
  return [{ json: { _hmacValid: false, _hmacError: 'requestedAt is in the future (>30s). Clock skew tolerance exceeded.' } }];
}
if (age > 5 * 60 * 1000) {
  return [{ json: { _hmacValid: false, _hmacError: 'Offer request expired (older than 5 minutes). Replay rejected.' } }];
}

// ── Valid: spread payload at root, add routing flag ──
return [{ json: { ...payload, _hmacValid: true } }];

// ─── Batch 7 | Normalize Offer Payload ───────────────────────────────────────
// Validates required fields and normalizes offer data types.
// Applies multi-layer sanitization to free-text fields:
//   sanitize()     — strips {{ }} n8n expression delimiters, caps length
//   escapeSlack()  — escapes &, <, > to prevent Slack mrkdwn link injection
//   stripFormula() — prefixes leading formula chars (belt-and-suspenders over RAW mode)
// Slack-escaped variants (_slack*) are used by the Slack approval message.
// Strips internal _hmacValid routing flag before downstream nodes see the payload.
// Sets execution context so error handler can identify affected candidate.
// ─────────────────────────────────────────────────────────────────────────────

const input = $input.first().json;

// ── Sanitization helpers ──
// Strip n8n expression delimiters from free-text fields
const sanitize = (v, maxLen = 3000) =>
  String(v ?? '').trim()
    .replace(/\{\{[\s\S]*?\}\}/g, '')
    .substring(0, maxLen);

// Escape Slack mrkdwn <url|text> link injection vectors
const escapeSlack = (v) =>
  v.replace(/&/g, '&amp;')
   .replace(/</g, '&lt;')
   .replace(/>/g, '&gt;');

// Prevent leading formula chars being interpreted if data is re-imported to another sheet
const stripFormula = (v) => /^[=+\-@]/.test(v) ? ' ' + v : v;

// ── Required field validation ──
const required = ['candidateName', 'candidateEmail', 'roleApplied', 'offerDetails'];
for (const field of required) {
  if (!input[field]) {
    throw new Error('Missing required field: ' + field + '. Offer payload rejected.');
  }
}

const candidateName  = String(input.candidateName).trim();
const roleApplied    = sanitize(input.roleApplied, 200);
const clientName     = sanitize(input.clientName ?? '', 200) || 'Client';
const offerDetails   = stripFormula(sanitize(input.offerDetails));

const payload = {
  candidateName,
  candidateEmail:      String(input.candidateEmail).trim().toLowerCase(),
  roleApplied,
  clientName,
  offerDetails,
  // Slack-escaped variants for approval message (prevents <url|text> link injection)
  _slackCandidateName: escapeSlack(candidateName),
  _slackRoleApplied:   escapeSlack(roleApplied),
  _slackClientName:    escapeSlack(clientName),
  _slackOfferDetails:  escapeSlack(offerDetails),
  offeredAt:           new Date().toISOString()
};

$execution.customData.set('candidate_name',  payload.candidateName);
$execution.customData.set('candidate_email', payload.candidateEmail);
$execution.customData.set('role_applied',    payload.roleApplied);
$execution.customData.set('stage',           'offer_gate');

return [{ json: payload }];
